{
  "mechanisms": [
    {
      "name": "asymmetric_learning_rates",
      "title": "Asymmetric Learning Rates",
      "description": "Separate learning rates are used for positive and negative prediction errors.",
      "params": [
        {
          "name": "alpha_pos",
          "bounds": [0, 1]
        },
        {
          "name": "alpha_neg",
          "bounds": [0, 1]
        }
      ],
      "evidence": "alpha_s1 = alpha_pos if delta_stage1 >= 0 else alpha_neg\n        alpha_s2 = alpha_pos if delta_stage2 >= 0 else alpha_neg",
      "expressible_in_slots": true
    },
    {
      "name": "eligibility_trace",
      "title": "Eligibility Trace",
      "description": "Stage-1 model-free values are updated by the stage-2 prediction error scaled by an eligibility trace parameter.",
      "params": [
        {
          "name": "lam",
          "bounds": [0, 1]
        }
      ],
      "evidence": "q_stage1_mf[action_1[trial]] += alpha_s1 * delta_stage1 + alpha_s2 * lam * delta_stage2",
      "expressible_in_slots": true
    },
    {
      "name": "mb_mf_mixture",
      "title": "MB/MF Mixture Weight",
      "description": "Stage-1 action values are a weighted sum of model-based and model-free values.",
      "params": [
        {
          "name": "w",
          "bounds": [0, 1]
        }
      ],
      "evidence": "q_net = w * q_stage1_mb + (1 - w) * q_stage1_mf",
      "expressible_in_slots": true
    },
    {
      "name": "unchosen_value_decay",
      "title": "Unchosen Value Decay",
      "description": "Values of unchosen actions at both stages decay towards zero.",
      "params": [
        {
          "name": "decay",
          "bounds": [0, 1]
        }
      ],
      "evidence": "unchosen_1 = 1 - action_1[trial]\n        q_stage1_mf[unchosen_1] *= (1 - decay)\n        \n        for s in range(2):\n            for a in range(2):\n                if s != state_idx or a != action_2[trial]:\n                    q_stage2_mf[s, a] *= (1 - decay)",
      "expressible_in_slots": true
    }
  ]
}
